<?php
/** Proof — customers and contacts (spec "Proof", 1). */
require __DIR__ . '/lib.php';
$vera = as_member(26); $bea = as_member(27); $carl = as_member(28); $owner = as_member(1);
ar_fixture();
echo "1. Customers\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/customers/save.php', ['name' => 'SMOKE Acme', 'email' => 'ap@acme.invalid', 'phone' => '555-0100', 'billing_address' => '1 Acme Way', 'terms_days' => '15', 'currency' => 'usd', 'notes' => 'SMOKE a private note']);
$acme = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $acme > 0 && ($b['location'] ?? '') === '/customers/' . $acme . '?notice=saved', "customer_save: 200, record_id $acme");
$log = activity('customer.save', $since);
ok(count($log) === 1 && (int) $log[0]['customer_id'] === $acme && !str_contains((string) $log[0]['after'], 'acme.invalid') && !str_contains((string) $log[0]['after'], 'private note') && str_contains((string) $log[0]['after'], '"email": "(set)"'), 'customer.save logs customer_id and never an address or a note (just "(set)")');
ok((string) one('SELECT currency FROM customers WHERE id = :i', ['i' => $acme]) === 'USD', 'the currency is upper-cased');
[$c, $b] = act($bea, '/customers/save.php', ['name' => 'smoke acme']);
ok($c === 422 && msg($b) === 'A customer named smoke acme exists.', 'a duplicate name (case-blind): 422');
[$c, $b] = act($bea, '/customers/save.php', ['name' => '', 'email' => 'nope', 'currency' => 'dollars', 'terms_days' => '999']);
$f = fields($b);
ok($c === 422 && isset($f['name'], $f['email'], $f['currency'], $f['terms_days']), 'bad fields: 422 with a field error each (' . implode(', ', array_keys($f)) . ')');
[$c, $b] = act($bea, '/customers/save.php', ['customer' => $acme, 'phone' => '555-0199']);
ok($c === 200 && (string) one('SELECT name FROM customers WHERE id = :i', ['i' => $acme]) === 'SMOKE Acme' && (string) one('SELECT phone FROM customers WHERE id = :i', ['i' => $acme]) === '555-0199' && (int) one('SELECT terms_days FROM customers WHERE id = :i', ['i' => $acme]) === 15, 'an update with one field keeps the rest');
echo "2. Who sees the address\n";
$body = page($bea, '/customers/')['body'];
ok(str_contains($body, 'ap@acme.invalid'), 'a Bookkeeper\'s card carries the email');
$body = page($vera, '/customers/')['body'];
ok(!str_contains($body, 'ap@acme.invalid') && str_contains($body, 'id="customer-card-' . $acme . '"'), 'a Viewer sees the card without the email');
$body = page($vera, '/customers/' . $acme)['body'];
ok(page($vera, '/customers/' . $acme)['code'] === 200 && !str_contains($body, 'ap@acme.invalid') && !str_contains($body, 'SMOKE a private note') && !str_contains($body, 'id="customer-contacts"'), 'a Viewer\'s page has no email, no note, no contacts panel');
$body = page($bea, '/customers/' . $acme)['body'];
ok(str_contains($body, 'ap@acme.invalid') && str_contains($body, 'SMOKE a private note') && str_contains($body, 'id="customer-contacts"'), 'a Bookkeeper\'s page has all three');
[$c, $d] = screen($vera, '/customers/' . $acme);
ok($d['customer']['email'] === null && $d['customer']['notes'] === null, 'the JSON for a Viewer carries no email and no notes');
[$c, $b] = act($vera, '/customers/save.php', ['name' => 'SMOKE Nope']);
ok($c === 403 && msg($b) === 'You may not keep the receivables.', 'a Viewer saving: 403 in the right\'s sentence');
echo "3. Contacts\n";
$since = last_activity_id();
[$c, $b] = act($bea, '/customers/contact.php', ['party_kind' => 'customer', 'party' => $acme, 'name' => 'SMOKE Ann Payable', 'email' => 'ann@acme.invalid', 'role' => 'Accounts payable', 'is_primary' => 'yes']);
$k1 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && $k1 > 0 && (bool) one('SELECT is_primary FROM party_contacts WHERE id = :k', ['k' => $k1]), 'contact_save: added as the primary');
$log = activity('contact.save', $since);
ok(count($log) === 1 && !str_contains((string) $log[0]['after'], 'ann@acme') && str_contains((string) $log[0]['after'], '"has_email": true'), 'contact.save logs that there is an email, never the address');
[$c, $b] = act($bea, '/customers/contact.php', ['party_kind' => 'customer', 'party' => $acme, 'name' => 'SMOKE Bob Owner', 'is_primary' => 'yes']);
$k2 = (int) ($b['record_id'] ?? 0);
ok($c === 200 && (bool) one('SELECT is_primary FROM party_contacts WHERE id = :k', ['k' => $k2]) && !(bool) one('SELECT is_primary FROM party_contacts WHERE id = :k', ['k' => $k1]), 'a contact made primary un-primaries the other');
[$c, $b] = act($bea, '/customers/contact.php', ['party_kind' => 'customer', 'party' => $acme, 'contact' => $k1, 'role' => 'AP clerk']);
ok($c === 200 && (string) one('SELECT name FROM party_contacts WHERE id = :k', ['k' => $k1]) === 'SMOKE Ann Payable' && (string) one('SELECT role FROM party_contacts WHERE id = :k', ['k' => $k1]) === 'AP clerk', 'a contact update keeps the rest');
[$c, $b] = act($bea, '/customers/contact.php', ['party_kind' => 'customer', 'party' => $acme, 'name' => 'SMOKE Bad', 'email' => 'nope']);
ok($c === 422 && isset(fields($b)['email']), 'a bad contact email: 422');
[$c, $b] = act($bea, '/customers/contact.php', ['party_kind' => 'planet', 'party' => $acme, 'name' => 'x']);
ok($c === 422, 'an unknown party kind: 422');
[$c, $b] = act($bea, '/customers/contact-remove.php', ['contact' => $k2]);
ok($c === 200 && one('SELECT 1 FROM party_contacts WHERE id = :k', ['k' => $k2]) === false, 'contact_remove');
echo "4. Archive and delete\n";
$beta = mk_customer('SMOKE Beta Corp');
$inv = mk_invoice($beta, [['Consulting', '1', '100.00']]);
issue($inv);
[$c, $b] = act($bea, '/customers/archive.php', ['customer' => $beta]);
ok($c === 422 && msg($b) === 'Settle or void its 1 open invoice first.', 'archive refused with an open invoice: "Settle or void its 1 open invoice first."');
[$c, $b] = act($bea, '/customers/save.php', ['customer' => $beta, 'currency' => 'EUR']);
ok($c === 422 && msg($b) === 'The currency is fixed once SMOKE Beta Corp has a document.', 'the currency is fixed after an invoice');
[$c, $b] = act($carl, '/customers/delete.php', ['customer' => $beta]);
ok($c === 422 && msg($b) === 'SMOKE Beta Corp has invoices; archive it instead.', 'delete refused with a document, in words: "… has invoices; archive it instead."');
[$c, $b] = act($bea, '/customers/delete.php', ['customer' => $beta]);
ok($c === 403, 'a Bookkeeper may not delete (journal.override)');
$gamma = mk_customer('SMOKE Gamma Empty');
$since = last_activity_id();
[$c, $b] = act($bea, '/customers/archive.php', ['customer' => $gamma]);
ok($c === 200 && one('SELECT archived_at FROM customers WHERE id = :i', ['i' => $gamma]) !== null && count(activity('customer.archive', $since)) === 1, 'a customer with nothing open archives; customer.archive logged');
ok(!in_array($gamma, array_column(screen($bea, '/customers/')[1]['customers'], 'customer_id'), true) && in_array($gamma, array_column(screen($bea, '/customers/?include_archived=1')[1]['customers'], 'customer_id'), true), 'archived is hidden unless include_archived');
[$c, $b] = act($bea, '/customers/archive.php', ['customer' => $gamma, 'archived' => 'no']);
ok($c === 200 && one('SELECT archived_at FROM customers WHERE id = :i', ['i' => $gamma]) === null, 'and restored');
$since = last_activity_id();
[$c, $b] = act($carl, '/customers/delete.php', ['customer' => $gamma]);
ok($c === 200 && one('SELECT 1 FROM customers WHERE id = :i', ['i' => $gamma]) === false && count(activity('customer.delete', $since)) === 1, 'a customer with no document at all is deleted by an override (logged)');
echo "5. The page\n";
$body = page($bea, '/customers/' . $beta)['body'];
ok(str_contains($body, 'id="customer-open-' . $inv . '"') && str_contains($body, 'id="customer-view-balance"') && str_contains($body, '100.00 USD'), 'the open invoice and the balance due show');
[$c, $d] = screen($bea, '/customers/?q=Beta');
ok(count($d['customers']) === 1 && $d['customers'][0]['balance_due'][0]['balance'] === '100.00' && $d['customers'][0]['open_invoices'] === 1, 'the list: the balance per currency and the open count');
$r = req('GET', '/customers/' . $acme . '/statement', ['jar' => $bea]);
ok($r['code'] === 200 && str_contains($r['body'], 'id="customer-statement-send-btn"'), 'the customer statement page (slice 3\'s report with the customer fixed) answers with a Send button (' . $r['code'] . ')');
ok(page($bea, '/customers/424242')['code'] === 404, 'an unknown customer: 404');
finish();
